openwrt_dts_main.ar9342_ubnt_nanostation-loco-m-xw.dts:
// SPDX-License-Identifier: GPL-2.0-or-later OR MIT

#include "ar9342_ubnt_xw_rssileds.dtsi"

/ {
	compatible = "ubnt,nanostation-loco-m-xw", "ubnt,xw", "qca,ar9342";
	model = "Ubiquiti Nanostation Loco M (XW)";
};

&mdio0 {
	status = "okay";

	phy1: ethernet-phy@1 {
		reg = <1>;
		phy-mode = "mii";
		reset-gpios = <&gpio 0 GPIO_ACTIVE_LOW>;
	};
};

&eth0 {
	status = "okay";

	phy-handle = <&phy1>;
};

openwrt_dts_main.ar9342_ubnt_nanostation-loco-m-xw-v2.dts:
// SPDX-License-Identifier: GPL-2.0-or-later OR MIT

#include "ar9342_ubnt_xw_rssileds.dtsi"

/ {
	compatible = "ubnt,nanostation-loco-m-xw-v2", "ubnt,xw", "qca,ar9342";
	model = "Ubiquiti Nanostation Loco M (XW) v2";
};

&mdio0 {
	status = "okay";

	phy4: ethernet-phy@4 {
		reg = <4>;
	};
};

&eth0 {
	status = "okay";

	/* default for ar934x, except for 1000M and 10M */
	pll-data = <0x02000000 0x00000101 0x00001313>;

	phy-mode = "rgmii-id";
	phy-handle = <&phy4>;

	gmac-config {
		device = <&gmac>;
		rxd-delay = <3>;
		rxdv-delay = <3>;
	};
};
